/* ===================== Dữ liệu đề thi nhúng sẵn (embedded) ===================== */
/* Dữ liệu đề thi + termbase/enrichment tiếng Việt được nhúng dưới dạng gzip+base64 (thay vì
   JSON thô) để giảm ~72% dung lượng file. Giải nén bằng DecompressionStream — API gzip chuẩn
   có sẵn trong trình duyệt (Chrome/Edge 80+, Safari 16.4+, Firefox 113+), không cần thư viện
   ngoài. Vì giải nén là bất đồng bộ, các cấu trúc dữ liệu suy ra từ đó (QUIZ_CATALOG,
   QUESTION_INDEX...) khởi tạo rỗng rồi được điền đầy đủ TRƯỚC khi App render lần đầu (xem
   initEmbeddedData() + cổng "loaded" trong component App). Module này không import React —
   thuần logic tải/giải nén dữ liệu. */

const QUIZ_EMBED_GZ_B64 = "";

const VI_TERMBASE_GZ_B64 = "";

const VI_ENRICHMENT_GZ_B64 = "";

/* ---------- Giải nén dữ liệu nhúng ---------- */
/* Dữ liệu đề thi + bản dịch tiếng Việt được nhúng dưới dạng gzip+base64 (thay vì JSON thô)   */
/* để giảm ~72% dung lượng file — cần thiết vì nền tảng publish artifact có giới hạn kích      */
/* thước, và JSON tiếng Anh/Việt lặp từ vựng nhiều nên nén rất hiệu quả. Giải nén bằng          */
/* DecompressionStream — API gzip chuẩn có sẵn trong trình duyệt (Chrome/Edge 80+, Safari       */
/* 16.4+, Firefox 113+), không cần thư viện ngoài. Vì giải nén là bất đồng bộ, các cấu trúc dữ  */
/* liệu suy ra từ đó (QUIZ_CATALOG, QUESTION_INDEX...) khởi tạo rỗng rồi được điền đầy đủ TRƯỚC */
/* khi App render lần đầu (xem initEmbeddedData() + cổng "loaded" trong component App).         */
async function decompressBase64Gzip(b64) {
  const binaryStr = atob(b64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  const text = await new Response(stream).text();
  return JSON.parse(text);
}

export let QUIZ_CATALOG = [];
export let QUESTION_INDEX = new Map();
export let QUESTIONS_BY_QUIZ = new Map();
export let VI_TERM_INDEX = new Map();
export let VI_TERM_LIST = [];
export let VI_ITEM_INDEX = new Map();

let _embeddedDataPromise = null;
export function initEmbeddedData() {
  if (_embeddedDataPromise) return _embeddedDataPromise;
  _embeddedDataPromise = (async () => {
    const [quizEmbed, viTermbase, viEnrichmentByQuiz] = await Promise.all([
      decompressBase64Gzip(QUIZ_EMBED_GZ_B64),
      decompressBase64Gzip(VI_TERMBASE_GZ_B64),
      decompressBase64Gzip(VI_ENRICHMENT_GZ_B64),
    ]);

    QUIZ_CATALOG = quizEmbed.catalog.slice().sort((a, b) => a.stageOrder - b.stageOrder || a.quizIndex - b.quizIndex);
    for (const c of QUIZ_CATALOG) {
      const list = (quizEmbed.data[String(c.quizIndex)] || []).slice().sort((a, b) => a.questionNumber - b.questionNumber);
      QUESTIONS_BY_QUIZ.set(c.quizIndex, list);
      for (const q of list) QUESTION_INDEX.set(q.id, q);
    }

    for (const t of viTermbase.terms || []) VI_TERM_INDEX.set(t.id, t);
    VI_TERM_LIST = (viTermbase.terms || []).slice().sort((a, b) => {
      const ea = (a.sourceTerms && a.sourceTerms[0]) || a.termVi;
      const eb = (b.sourceTerms && b.sourceTerms[0]) || b.termVi;
      return ea.localeCompare(eb);
    });

    for (const key of Object.keys(viEnrichmentByQuiz)) {
      const pack = viEnrichmentByQuiz[key];
      for (const qid of Object.keys(pack.items)) {
        VI_ITEM_INDEX.set(qid, pack.items[qid]);
      }
    }
  })();
  return _embeddedDataPromise;
}
